export interface HotkeyBindingOptions {
  /**
   * When true, the binding still fires while an input, textarea or
   * contenteditable element has focus.
   */
  allowInInput?: boolean;
  /** Optional scope this binding lives in (defaults to the current scope). */
  scope?: string;
}

interface ParsedChord {
  key: string;
  ctrl: boolean;
}

export interface Unbind {
  (): void;
}

export interface Hotkeys {
  /** Bind a single chord ("mod+k") or a sequence ("g d"). Returns an unbind fn. */
  bind(chord: string, handler: (event: KeyboardEvent) => void, options?: HotkeyBindingOptions): Unbind;
  /** Push a named scope; only bindings in the top scope fire. */
  push(scope: string): void;
  /** Pop the current scope, restoring the previous one. */
  pop(): void;
  /** Current scope name. */
  readonly currentScope: string | undefined;
  /** Remove all bindings and reset scopes. */
  destroy(): void;
}

const SEQUENCE_TIMEOUT_MS = 800;

function parseBinding(binding: string): { chords: ParsedChord[]; isSequence: boolean } {
  const parts = binding.trim().split(/\s+/);
  const chords = parts.map((part) => {
    let ctrl = false;
    let key = '';
    for (const token of part.split('+')) {
      if (token === 'mod') {
        ctrl = true;
      } else {
        key = token.toLowerCase();
      }
    }
    return { key, ctrl };
  });
  return { chords, isSequence: chords.length > 1 };
}

function matchesChord(event: KeyboardEvent, chord: ParsedChord): boolean {
  const eventKey = event.key.toLowerCase();
  // "meta must also match it": mod requires ctrl; meta may additionally be
  // held but must not be required — i.e. meta on the binding means nothing.
  return eventKey === chord.key && event.ctrlKey === chord.ctrl && !event.altKey;
}

function isEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName.toLowerCase();
  if (tag === 'input' || tag === 'textarea') return true;
  if (target.isContentEditable) return true;
  return false;
}

export function createHotkeys(target: Window | HTMLElement = window): Hotkeys {
  type Entry = {
    chords: ParsedChord[];
    handler: (event: KeyboardEvent) => void;
    allowInInput: boolean;
    scope: string | undefined;
  };

  const bindings: Entry[] = [];
  const scopes: string[] = [];
  let pending: { chords: ParsedChord[]; index: number } | null = null;
  let timer: ReturnType<typeof setTimeout> | null = null;

  function clearPending() {
    pending = null;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function handleKeyDown(event: Event) {
    const ke = event as KeyboardEvent;
    const editable = isEditableTarget(ke.target);

    const candidates = bindings.filter((b) => b.scope === undefined || b.scope === scopes[scopes.length - 1]);

    // If a sequence is in progress, try to continue it first.
    if (pending) {
      const nextIndex = pending.index + 1;
      const expected = pending.chords[nextIndex];
      const match = candidates.find((b) => b.chords === pending!.chords && b.chords.length > nextIndex);
      if (expected && match && matchesChord(ke, expected)) {
        if (!match.allowInInput && editable) {
          clearPending();
          return;
        }
        if (nextIndex === match.chords.length - 1) {
          clearPending();
          ke.preventDefault();
          match.handler(ke);
        } else {
          pending = { chords: pending.chords, index: nextIndex };
          armTimer();
        }
        return;
      }
      clearPending();
    }

    for (const entry of candidates) {
      if (entry.allowInInput === false && editable) continue;
      const chord = entry.chords[0];
      if (entry.chords.length === 1 && matchesChord(ke, chord)) {
        ke.preventDefault();
        entry.handler(ke);
        return;
      }
      if (entry.chords.length > 1 && matchesChord(ke, chord)) {
        pending = { chords: entry.chords, index: 0 };
        armTimer();
        ke.preventDefault();
        return;
      }
    }
  }

  function armTimer() {
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => clearPending(), SEQUENCE_TIMEOUT_MS);
  }

  target.addEventListener('keydown', handleKeyDown);

  return {
    bind(chord, handler, options = {}) {
      const parsed = parseBinding(chord);
      const entry: Entry = {
        chords: parsed.chords,
        handler,
        allowInInput: options.allowInInput ?? false,
        scope: options.scope,
      };
      bindings.push(entry);
      return () => {
        const i = bindings.indexOf(entry);
        if (i !== -1) bindings.splice(i, 1);
      };
    },
    push(scope) {
      scopes.push(scope);
      clearPending();
    },
    pop() {
      scopes.pop();
      clearPending();
    },
    get currentScope() {
      return scopes[scopes.length - 1];
    },
    destroy() {
      clearPending();
      bindings.length = 0;
      scopes.length = 0;
      target.removeEventListener('keydown', handleKeyDown);
    },
  };
}

