  scope?: string;
}

interface ParsedChord {
  key: string;
  ctrl: boolean;
}

export interface Unbind {
  (): void;
}

export interface Hotkeys {
  /** Bind a single chord ("mod+k") or a two-key sequence ("g d"). */
  bind(chord: string, handler: (event: KeyboardEvent) => void, options?: HotkeyBindingOptions): Unbind;
  /** Push a named scope. While active, it shadows all other bindings. */
  push(scope: string): void;
  /** Pop the current scope, restoring the previous context. */
  pop(): void;
  /** Current top-of-stack scope name, or undefined when no scope is active. */
  readonly currentScope: string | undefined;
  /** Remove all bindings and reset scopes. */
  destroy(): void;
}

const SEQUENCE_TIMEOUT_MS = 800;

function parseBinding(binding: string): ParsedChord[] {
  return binding
    .trim()
    .split(/\s+/)
    .map((part) => {
      let ctrl = false;
      let key = '';
      for (const token of part.split('+')) {
        if (token === 'mod') {
          ctrl = true;
        } else if (token) {
          key = token.toLowerCase();
        }
      }
      return { key, ctrl };
    });
}

/**
 * `mod` means ctrl: the event must have ctrlKey set to match. Meta may not be
 * substituted for ctrl — an event carrying meta instead of ctrl does not match,
 * and one carrying both must still include ctrl.
 */
function matchesChord(event: KeyboardEvent, chord: ParsedChord): boolean {
  const eventKey = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  return (
    eventKey === chord.key &&
    event.ctrlKey === chord.ctrl &&
    !event.altKey &&
    !(chord.ctrl && !event.ctrlKey)
  );
}

function isEditableTarget(t: EventTarget | null): boolean {
  if (!(t instanceof HTMLElement)) return false;
  const tag = t.tagName.toLowerCase();
  return tag === 'input' || tag === 'textarea' || t.isContentEditable;
}

export function createHotkeys(target: Window | HTMLElement = window): Hotkeys {
  interface Entry {
    chords: ParsedChord[];
    handler: (event: KeyboardEvent) => void;
    allowInInput: boolean;
    scope: string | undefined;
  }

  const entries: Entry[] = [];
  const scopes: string[] = [];
  let pending: { entry: Entry; index: number } | null = null;
  let timer: ReturnType<typeof setTimeout> | null = null;

  function armTimer() {
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => {
      pending = null;
      timer = null;
    }, SEQUENCE_TIMEOUT_MS);
  }

  function clearPending() {
    pending = null;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function activeCandidates(): Entry[] {
    const top = scopes[scopes.length - 1];
    // An active scope fully shadows everything outside itself.
    return entries.filter((e) => e.scope === top);
  }

  function handleKeyDown(event: Event) {
    const ke = event as KeyboardEvent;
    const editable = isEditableTarget(ke.target);
    const candidates = activeCandidates();

    // Continue an in-flight sequence?
    if (pending && pending.entry.chords[pending.index + 1]) {
      const expected = pending.entry.chords[pending.index + 1];
      if (matchesChord(ke, expected)) {
        const entry = pending.entry;
        if (!entry.allowInInput && editable) {
          clearPending();
          return;
        }
        if (pending.index + 1 === entry.chords.length - 1) {
          clearPending();
          ke.preventDefault();
          entry.handler(ke);
        } else {
          pending = { entry, index: pending.index + 1 };
          armTimer();
        }
        return;
      }
      clearPending();
    }

    for (const entry of candidates) {
      if (!entry.allowInInput && editable) continue;
      const chord = entry.chords[0];
      if (!matchesChord(ke, chord)) continue;

      ke.preventDefault();
      if (entry.chords.length === 1) {
        entry.handler(ke);
      } else {
        pending = { entry, index: 0 };
        armTimer();
      }
      return;
    }
  }

  target.addEventListener('keydown', handleKeyDown);

  return {
    bind(chord, handler, options = {}) {
      const entry: Entry = {
        chords: parseBinding(chord),
        handler,
        allowInInput: options.allowInInput ?? false,
        scope: options.scope,
      };
      entries.push(entry);
      return () => {
        const i = entries.indexOf(entry);
        if (i !== -1) entries.splice(i, 1);
      };
    },
    push(scope) {
      scopes.push(scope);
      clearPending();
    },
    pop() {
      scopes.pop();
      clearPending();
    },
    get currentScope() {
      return scopes[scopes.length - 1];
    },
    destroy() {
      clearPending();
      entries.length = 0;
      scopes.length = 0;
      target.removeEventListener('keydown', handleKeyDown);
    },
  };
