import { describe, expect, it, vi, beforeEach, afterEach } from 'vitest';
import { createHotkeys, type Hotkeys } from '../src/hotkeys';

function keydown(key: string, init: Partial<KeyboardEventInit> = {}): KeyboardEvent {
  const event = new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true, ...init });
  document.dispatchEvent(event);
  return event;
}

describe('createHotkeys', () => {
  let hk: Hotkeys;

  beforeEach(() => {
    vi.useFakeTimers();
    hk = createHotkeys(document);
  });

  afterEach(() => {
    hk.destroy();
    vi.useRealTimers();
  });

  describe('single chords', () => {
    it('fires on mod+k (ctrl held)', () => {
      const handler = vi.fn();
      hk.bind('mod+k', handler);
      const ev = keydown('k', { ctrlKey: true });
      expect(handler).toHaveBeenCalledTimes(1);
      expect(handler).toHaveBeenCalledWith(ev);
    });

    it('requires ctrl for mod bindings (meta alone must not match)', () => {
      const handler = vi.fn();
      hk.bind('mod+k', handler);
      keydown('k', { metaKey: true });
      expect(handler).not.toHaveBeenCalled();
    });

    it('meta+ctrl matches a mod binding since ctrl is present', () => {
      const handler = vi.fn();
      hk.bind('mod+k', handler);
      keydown('k', { ctrlKey: true, metaKey: true });
      expect(handler).toHaveBeenCalledOnce();
    });

    it('does not fire without modifier', () => {
      const handler = vi.fn();
      hk.bind('mod+k', handler);
      keydown('k');
      expect(handler).not.toHaveBeenCalled();
    });

    it('unbind works', () => {
      const handler = vi.fn();
      const unbind = hk.bind('mod+k', handler);
      unbind();
      keydown('k', { ctrlKey: true });
      expect(handler).not.toHaveBeenCalled();
    });
  });

  describe('two-key sequences', () => {
    it('completes "g d" when second key arrives within the timeout', () => {
      const handler = vi.fn();
      hk.bind('g d', handler);
      keydown('g');
      expect(handler).not.toHaveBeenCalled();
      keydown('d');
      expect(handler).toHaveBeenCalledOnce();
    });

    it('does not fire on first key alone', () => {
      const handler = vi.fn();
      hk.bind('g d', handler);
      keydown('g');
      vi.advanceTimersByTime(700);
      keydown('d'); // still within window
      expect(handler).toHaveBeenCalledOnce();
    });

    it('expires if the second key arrives later than 800ms', () => {
      const handler = vi.fn();
      hk.bind('g d', handler);
      keydown('g');
      vi.advanceTimersByTime(801);
      keydown('d');
      expect(handler).not.toHaveBeenCalled();

      // After expiry, a fresh "g d" still completes.
      keydown('g');
      keydown('d');
      expect(handler).toHaveBeenCalledOnce();
    });
  });

  describe('scopes', () => {
    it('pushed scope shadows global bindings', () => {
      const globalHandler = vi.fn();
      const scopedHandler = vi.fn();
      hk.bind('mod+k', globalHandler);
      hk.bind('mod+k', scopedHandler, { scope: 'modal' });

      hk.push('modal');
      keydown('k', { ctrlKey: true });
      expect(scopedHandler).toHaveBeenCalledOnce();
